<!doctype html>
<html lang="es"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width, initial-scale=1"><title>Informes | CampoSur</title><link rel="stylesheet" href="assets/css/app.css"></head><body class="admin-page"><main class="admin-shell"><?php require dirname(__DIR__) . '/Views/partials/module-navigation.php'; ?><section class="module-content"><header class="admin-header"><div><p class="eyebrow">Informes</p><h1>Informes de la agrícola</h1><p class="setup-copy">Revisa tus costos y movimientos registrados.</p></div><div class="header-actions"><a class="secondary-link" href="?module=reports&export=csv">Descargar CSV</a><a class="secondary-link" href="./">Volver al dashboard</a></div></header><section class="kpi-grid"><article class="report-kpi"><span>Costo registrado</span><b>$<?= number_format((float) $summary['total'], 0, ',', '.') ?></b></article><article class="report-kpi"><span>Movimientos</span><b><?= number_format((int) $summary['entries'], 0, ',', '.') ?></b></article><article class="report-kpi"><span>Clasificaciones</span><b><?= count($categories) ?></b></article><article class="report-kpi"><span>Temporadas</span><b><?= count($seasons) ?></b></article></section><section class="admin-columns"><article class="admin-panel"><header class="panel-header"><h2>Costos por clasificación</h2><p>Distribución de gastos registrados</p></header><div class="report-bars"><?php $maxCategory = max(array_map(fn ($row) => (float) $row['total'], $categories) ?: [1]); foreach ($categories as $row): ?><div class="report-bar-row"><span><?= htmlspecialchars($row['category']) ?></span><div class="report-bar"><i></i></div><b>$<?= number_format((float) $row['total'], 0, ',', '.') ?></b></div><?php endforeach; ?></div></article><article class="admin-panel"><header class="panel-header"><h2>Costos por temporada</h2><p>Comparación acumulada</p></header><div class="role-list"><?php foreach ($seasons as $row): ?><div class="role-row"><b><?= htmlspecialchars($row['name']) ?></b><span>$<?= number_format((float) $row['total'], 0, ',', '.') ?></span></div><?php endforeach; ?></div></article></section><section class="admin-panel"><header class="panel-header"><h2>Costos por fundo</h2><p>Apoyo para decisiones operativas</p></header><div class="table-scroll"><table class="admin-table"><thead><tr><th>Fundo</th><th>Costo acumulado</th></tr></thead><tbody><?php foreach ($farms as $row): ?><tr><td><b><?= htmlspecialchars($row['name']) ?></b></td><td><b>$<?= number_format((float) $row['total'], 0, ',', '.') ?></b></td></tr><?php endforeach; ?></tbody></table></div></section></section></main></body></html>
